import numpy as np
import time

def run_packing() -> tuple[np.ndarray, np.ndarray, float]:
    rng = np.random.default_rng(0)
    n = 26
    max_iter = 1000
    time_budget = 5.0
    start_time = time.time()

    # Initial grid-like layout with slight jitter
    row_counts = [5, 5, 5, 5, 6]
    rows = len(row_counts)
    ys = np.linspace(1.0/(rows+1), rows/(rows+1), rows)
    centers = []
    for ri, m in enumerate(row_counts):
        xs = np.linspace(1.0/(m+1), m/(m+1), m)
        if ri % 2 == 1 and m > 1:
            xs += (xs[1] - xs[0]) * 0.3
        for x in xs:
            centers.append([x, ys[ri]])
    centers = np.array(centers, dtype=float)
    centers += rng.normal(scale=1e-3, size=centers.shape)
    centers = np.clip(centers, 1e-3, 1 - 1e-3)
    radii = np.full(n, 1e-3, dtype=float)

    # Precomputed distance matrix (with self-diag as infinity)
    diff = centers[:, None, :] - centers[None, :, :]
    D = np.sqrt(np.sum(diff * diff, axis=2))
    np.fill_diagonal(D, np.inf)

    # Helper: compute max possible radius for a circle given others
    def max_radius_i(i):
        # Boundary limits
        b = min(centers[i, 0], 1 - centers[i, 0], centers[i, 1], 1 - centers[i, 1])
        # Pairwise limits
        caps = D[i] - radii
        caps[i] = np.inf
        return min(b, np.min(caps))

    # Main loop: insert circles greedily with periodic radii re-optimization
    insert_order = np.arange(n)
    np.random.shuffle(insert_order)

    for it in range(max_iter):
        if time.time() - start_time > time_budget:
            break
        # Re-optimize all radii locally
        improved = False
        last_sum = np.sum(radii)
        for _ in range(60):
            changed = False
            for i in range(n):
                new_r = max_radius_i(i)
                if abs(new_r - radii[i]) > 1e-10:
                    radii[i] = new_r
                    changed = True
            if not changed:
                break
        if np.sum(radii) > last_sum:
            improved = True

        if not improved:
            break

        # Greedily insert the next circle in order
        for i in insert_order:
            if radii[i] < 1e-5:
                # Place it with max possible radius
                new_r = max_radius_i(i)
                if new_r > 1e-5:
                    radii[i] = new_r
                    improved = True

        if not improved:
            break

    # Final polish: max radii for any remaining feasibility window
    for _ in range(80):
        changed = False
        for i in range(n):
            new_r = max_radius_i(i)
            if new_r > radii[i] + 1e-10:
                radii[i] = new_r
                changed = True
        if not changed:
            break

    # Adjust to strict feasibility
    for i in range(n):
        r_max = min(centers[i, 0], 1 - centers[i, 0], centers[i, 1], 1 - centers[i, 1])
        radii[i] = min(radii[i], r_max)
        for j in range(n):
            if i != j:
                dist = np.linalg.norm(centers[i] - centers[j])
                if dist < radii[i] + radii[j] - 1e-10:
                    delta = (radii[i] + radii[j] - dist) + 1e-12
                    if radii[i] >= radii[j]:
                        radii[i] = max(0.0, radii[i] - delta)
                    else:
                        radii[j] = max(0.0, radii[j] - delta)

    # Final re-optimization
    for _ in range(50):
        changed = False
        for i in range(n):
            new_r = max_radius_i(i)
            if abs(new_r - radii[i]) > 1e-10:
                radii[i] = new_r
                changed = True
        if not changed:
            break

    sum_radii = float(np.sum(radii))
    return centers.astype(float), radii.astype(float), sum_radii
